  out.push({ key: 'usd', kind: 'usd', name: DL('Buy USD', 'USD al'), mult: dlFxMult(t), sig: (+S.fxVol || 8) / 100 * Math.sqrt(t), factor: 'fx' });
  const g = state.map.GAUTRY; if (g && g.e && g.e.price) { const ex = dlLineExpect(g, 1e5, t); if (ex) out.push({ key: 'line:GAUTRY', kind: 'stock', sym: 'GAUTRY', x: g, name: DL('Gram gold', 'Gram altın'), mult: ex.mult, sig: ex.sig, factor: 'mkt' }); }
