  const bm = base.map(b => ({ ...b, x: state.map[b.symbol] || state.inst[b.symbol], r: dlRetMap(b.symbol) })).filter(b => b.x && b.r.size > 60);
  if (!bm.length) return []; const wsum = bm.reduce((a, b) => a + b.w, 0) || 1; bm.forEach(b => b.w /= wsum);
