function dlAddNextRows(list, amount) { return list.map(c => `<tr class="row" data-sym="${esc(c.x.symbol)}"><td class="l acc">${esc(c.x.symbol)} <span class="dim txt">${esc((c.x.name || '').slice(0, 24))}</span></td><td>${c.x.score ?? '—'}</td><td class="up">${fmtPct(c.e.excess)}</td><td>${c.rho.toFixed(2)}</td><td>${Math.round(c.w * 100)}%${amount ? ` <span class="dim">· ${T(amount * c.w)}</span>` : ''}</td><td class="l">${[c.rho < 0.3 ? DL('moves differently', 'farklı hareket ediyor') : '', c.newSector ? DL('new sector', 'yeni sektör') : '', c.x.score >= 90 ? DL('top score', 'en üst puan') : '', c.x.symbol === 'GAUTRY' ? DL('hedge against TRY', 'TL’ye karşı koruma') : ''].filter(Boolean).map(t => `<span class="pill">${t}</span>`).join(' ')}</td></tr>`).join(''); }
const DL_ADDHEAD = () => `<tr><th class="l">${DL('Add', 'Ekle')}</th><th>${DL('Score', 'Puan')}</th><th title="${DL('Expected 1-year return over the deposit, after costs and tax', 'Mevduata göre beklenen 1 yıllık fazla getiri, maliyet ve vergi sonrası')}">${DL('Over deposit', 'Mevduata göre')}</th><th title="${DL('Correlation of daily returns with what you hold (1 = moves together)', 'Elinizdekilerle günlük getiri korelasyonu (1 = birlikte hareket)')}">ρ</th><th>${DL('Suggested share', 'Önerilen pay')}</th><th class="l">${DL('Why', 'Neden')}</th></tr>`;
