    if (q.x && q.x.e) { const e = dlExp1y(q.x, q.valueTRY); mu = e ? e.mu : dep; sig = e ? e.sig : 25; }
    else if (q.kind === 'try_dep') mu = q.demand ? 0 : dep; else if (q.kind === 'try_cash') mu = 0; else if (q.kind === 'usd_cash') { mu = fx; sig = +state.S.fxVol || 12; } else if (q.kind === 'usd_dep') { mu = fx + (+state.S.rfUsd || 3) * 0.6; sig = +state.S.fxVol || 12; }
