  const c = 0.75 * cfo, y1 = cash + c - (capex || 0) - div - d1, y2 = y1 + c - (capex || 0) - div - (d2 || 0), v = y1 >= 0 && y2 >= 0 ? 'good' : y1 < 0 ? 'bad' : 'warn';
