  if (c.rdcf && c.rdcf.verdict === 'bad') add('value', 8, c.rdcf.head, DL('the price leaves room for upside', 'fiyat yükselişe alan bırakır'), DL('revenue growth below the implied rate in the next 2 quarters', 'önümüzdeki 2 çeyrekte gelir büyümesinin ima edilen oranın altında kalması'));
