const BD_V = BD_M.filter(m => !m.nv), BD_BY = Object.fromEntries(BD_M.map(m => [m.id, m]));
const bdT = (en, tr) => DL(en, tr), bdN = (v, d = 1) => v == null || !isFinite(v) ? '—' : dlN(v, d), bdP = (v, d = 1) => v == null || !isFinite(v) ? '—' : (v >= 0 ? '+' : '−') + '%' + dlN(Math.abs(v), d);
