    const real = f.tr && f.infl != null ? g - f.infl : g, peg = real > 0 ? f.pe / real : null, s = peg == null ? -0.3 : peg < 0.8 ? 0.6 : peg < 1.3 ? 0.2 : peg > 2.5 ? -0.5 : -0.15;
