function bdJudge(id, f) { try { const r = BD_LENS[id](f) || [0, '']; return { s: bdClip(r[0]), t: r[1], weak: !!r[2] }; } catch (e) { console.error('board lens', id, e); return { s: 0, t: bdT('No view.', 'Görüş yok.'), weak: true }; } }
