  if (/brüt takas|vbts/.test(t)) return { ...o, kind: 'legal', sub: 'vbts' }; if (/açığa satış|short sell/.test(t)) return { ...o, kind: 'legal', sub: 'short' };
  if (/viop|vadeli|kontrat|teminat|vade dönüm|futures?/.test(t)) { let under = null; for (const [k, re] of Object.entries(BD_UNDER)) if (re.test(t)) { under = k; break; } if (!under && syms[0]) under = syms[0]; if (!under) under = /dolar|usd/.test(t) ? 'USD' : /altın|gold/.test(t) ? 'GOLD' : 'XU030';
    return { ...o, kind: 'viop', under, sub: /koru|hedge/.test(t) ? 'hedge' : /teminat tamamlama|margin call/.test(t) ? 'call' : /vade dönüm|roll/.test(t) ? 'roll' : /kaç kontrat|ne kadar teminat|how many/.test(t) ? 'size' : 'dir' }; }
  if (syms.length >= 2 && /\bmi\b|\bmı\b|\bmu\b|\bmü\b|\bvs\b|ile|hangisi|or\b/.test(t)) return { ...o, kind: 'cmp' };
