const BD_OC = { buy: '#2fa36b', add: '#2fa36b', long: '#2fa36b', keep: '#2fa36b', hold: '#3d7bd9', wait: '#8a8f98', flat: '#8a8f98', rebal: '#e0a92b', trim: '#e0a92b', sell: '#d0453a', avoid: '#d0453a', short: '#d0453a', shrink: '#d0453a', none: '#8a8f98' };
